const zn=xs=>{let z=1;while(z<8&&xs>=Z[z])z++;return z};
const hx=c=>{let h=c.slice(1);if(h.length==3)h=h[0]+h[0]+h[1]+h[1]+h[2]+h[2];return[parseInt(h.slice(0,2),16),parseInt(h.slice(2,4),16),parseInt(h.slice(4,6),16)]};
const mixs=(a,b,u)=>{const f=s=>s.charAt(0)=='#'?hx(s):s.match(/\d+/g).map(Number);const p=f(a),q=f(b);return'rgb('+Math.round(p[0]+(q[0]-p[0])*u)+','+Math.round(p[1]+(q[1]-p[1])*u)+','+Math.round(p[2]+(q[2]-p[2])*u)+')'};
const INTRO="Novecento, dall’alba alla notte. Parti da Genova, dove i camalli caricano le navi e migliaia di emigranti salgono a bordo con le valigie di cartone; poi Milano, dove un’intera città canta per il funerale di Verdi e un direttore d’orchestra dirige la Scala. Sulle montagne della Carnia le donne portano le gerle ai soldati; a mezzogiorno Roma, con un gruppo di giovani fisici che scopre i neutroni lenti. Nel primo pomeriggio Napoli, che si rialza dopo le bombe con il teatro di Eduardo; poi Torino, dove una piccola auto cambia la vita degli italiani e tutti guardano la Luna in televisione. Infine Palermo, che dice no alla mafia, e una notte svizzera in cui nasce la rete che oggi unisce il mondo. Il tempo qui si piega: operai, scienziati, artisti e cuochi di strada di ogni anno ti vengono incontro.";
const NZ=[8,7,7,7,10,8,9,8];
const LKTXT=[
"Genova è uno dei porti più grandi d’Italia: a inizio Novecento qui arrivano carbone, grano e cotone, e partono merci e persone. Sopra la città il faro della Lanterna guida da secoli i naviganti, e il porto non dorme mai.",
"I camalli sono i facchini del porto: la loro compagnia, detta dei Caravana, risale al 1340. Portano sulle spalle sacchi e casse e indossano un grembiule di tela blu, lo \"scossalin\": il \"Blu di Genova\" è considerato il progenitore dei jeans. Secondo la tradizione, i marinai genovesi hanno anche il \"diritto al mugugno\", cioè il diritto di brontolare.",
"Il 7 settembre 1893 alcuni inglesi fondano a Genova il Genoa Cricket and Athletic Club: all’inizio si gioca soprattutto a cricket. Un medico inglese, James Spensley, porta il calcio, e nel 1898 il Genoa vince il primo campionato italiano: è la squadra più antica d’Italia ancora in attività, e negli anni seguenti vince molti titoli.",
"Tra il 1876 e il 1915 più di quattordici milioni di italiani lasciano il Paese in cerca di lavoro: è la \"grande emigrazione\". Fra il 1876 e il 1901 circa sei emigranti su dieci si imbarcano proprio a Genova; poi, con il crescere delle partenze dal Sud, Napoli diventa il porto più affollato. Partono per le Americhe con una valigia di cartone e pochi soldi, spesso insieme alla famiglia.",
"La traversata dura molti giorni e i passeggeri di terza classe viaggiano stretti nel ponte inferiore. A New York gli emigranti sbarcano sull’isola di Ellis Island, aperta nel 1892 e chiusa nel 1954: qui medici e funzionari li controllano uno a uno, e quasi dodici milioni di persone di ogni Paese vi passano prima di entrare in America. Per questo molti la chiamano \"l’isola delle lacrime\", ma anche \"la porta dell’America\".",
"Guglielmo Marconi, nato a Bologna nel 1874, inventa un sistema per trasmettere segnali senza fili. Il 12 dicembre 1901, a Signal Hill, in Terranova, riceve tre brevi segnali, la lettera \"S\" in codice Morse, trasmessi dalla Cornovaglia, in Inghilterra, a più di tremila chilometri: è il primo segnale radio che attraversa l’oceano. Nel 1909 riceve il premio Nobel per la fisica.",
"Nell’aprile del 1912, quando il Titanic affonda nell’Atlantico, gli operatori radio con il sistema Marconi mandano segnali di soccorso: grazie a quei messaggi una nave vicina accorre e salva centinaia di persone. Da allora, per legge, le grandi navi devono avere un impianto radio e qualcuno sempre in ascolto.",
"Al mattino i camalli e i marinai mangiano una fetta di focaccia calda con l’olio, spesso inzuppata nel caffelatte, o un pezzo di farinata, la sottile torta di farina di ceci cotta nel forno a legna. Nei caruggi si vende anche il pesto, fatto nel mortaio con basilico, pinoli, formaggio, aglio e olio.",
"A inizio Novecento Milano è una città moderna, con circa mezzo milione di abitanti: i tram elettrici, i grandi giornali, le officine e le banche la rendono la città più attiva d’Italia. Il 29 luglio 1900, a Monza, il re Umberto I viene ucciso da un anarchico; sale al trono suo figlio Vittorio Emanuele III, e il secolo comincia con un grande lutto.",
"Giuseppe Verdi muore a Milano, nel suo albergo, il 27 gennaio 1901. Il primo funerale è semplice, all’alba, come lui voleva; un mese dopo, alla fine di febbraio, il suo corpo viene portato alla Casa di Riposo per Musicisti, da lui fondata per i vecchi artisti. Più di trecentomila persone seguono il corteo, e un coro di ottocentoventi voci, diretto da Arturo Toscanini, canta il \"Va, pensiero\" del Nabucco.",
"Dal 1898 Arturo Toscanini, nato a Parma nel 1867, dirige la Scala: è famoso per il carattere esigente, per le lunghe prove e per la memoria prodigiosa. Nel 1908 va a dirigere al Metropolitan di New York; tornerà alla Scala negli anni Venti. Nella sala a ferro di cavallo, con i palchi dorati, il pubblico ascolta ancora oggi le opere di Verdi e di Puccini.",
"Il 20 febbraio 1909 il poeta Filippo Tommaso Marinetti pubblica sul giornale francese \"Le Figaro\" il Manifesto del Futurismo, scritto a Milano: un gruppo di artisti, fra cui Umberto Boccioni, Carlo Carrà, Luigi Russolo, Giacomo Balla e Gino Severini, vuole rompere con il passato e celebrare la velocità, le macchine, le fabbriche e le città. Dipingono treni, tram, folle e automobili con linee spezzate e colori vivaci.",
"Il 13 maggio 1909 parte da Milano il primo Giro d’Italia in bicicletta, organizzato dalla \"Gazzetta dello Sport\", un giornale stampato su carta rosa, per vendere più copie. La corsa dura fino al 30 maggio e la vince Luigi Ganna, un ciclista lombardo ex muratore. Nei paesi la gente aspetta i corridori ai bordi della strada.",
"Attorno a Milano crescono le fabbriche: il vapore, l’elettricità e il ferro cambiano il lavoro. Nel 1910 nasce a Milano una nuova fabbrica di automobili, l’A.L.F.A. (Anonima Lombarda Fabbrica Automobili), che diventerà molto famosa; gli operai entrano ai turni con il suono della sirena. La città si riempie di operai, impiegati e botteghe.",
"Sotto la cupola di vetro e ferro della Galleria Vittorio Emanuele II, il \"salotto di Milano\", si incontrano nobili, commercianti, artisti e impiegati. Si prende il caffè, si legge il giornale, si compra un libro; di sera i locali si riempiono di musica.",
"Nel 1914 scoppia in Europa una guerra che coinvolge molti Paesi e poi anche altri continenti. L’Italia, dopo dieci mesi di neutralità, entra in guerra il 24 maggio 1915 contro l’Austria-Ungheria. Il fronte corre dalle Alpi Carniche fino all’Isonzo e al Carso: per più di tre anni si combatte fra montagne, neve e fango.",
"In Carnia gli uomini sono al fronte e le donne dei paesi come Paluzza e Timau portano in alto, ogni giorno, viveri, medicine e munizioni ai soldati. Sono dette \"portatrici\": caricano la gerla, un grande cesto di vimini, fino a quaranta chili, salgono per mille metri di dislivello e vengono pagate poco, meno degli uomini. Una di loro, Maria Plozner Mentil, madre di quattro figli, viene colpita il 15 febbraio 1916 e muore il giorno dopo: la sua storia diventa simbolo di tutte le portatrici.",
"Gli Alpini, i soldati di montagna con il cappello dalla penna nera, vivono sulle cime in baracche di legno e in gallerie scavate nella roccia, con il freddo, la neve e la fame. La vita al fronte è fatta di attese, di lavoro e di lettere: i soldati scrivono a casa su fogli e cartoline e aspettano il rancio caldo, spesso polenta e minestra.",
"Il 24 ottobre 1917, vicino a Caporetto, le truppe austro-tedesche rompono il fronte e l’esercito italiano si ritira per circa duecento chilometri fino al fiume Piave. Il comandante Luigi Cadorna viene sostituito da Armando Diaz; sul Monte Grappa e sul Piave l’esercito resiste e il fronte si ferma. Migliaia di profughi lasciano le loro case.",
"Il 24 ottobre 1918, esattamente un anno dopo Caporetto, l’esercito italiano attraversa il Piave e avanza verso Vittorio Veneto. Il 3 novembre l’Austria-Ungheria firma l’armistizio a Villa Giusti, vicino a Padova; entra in vigore a mezzogiorno del 4 novembre, quando il generale Diaz diffonde il bollettino della vittoria. Oggi il 4 novembre è la Giornata dell’Unità Nazionale e delle Forze Armate.",
"Il 28 ottobre 1921, nella basilica di Aquileia, una madre triestina di nome Maria Bergamas, il cui figlio era caduto in guerra senza mai essere ritrovato, sceglie fra undici bare uguali quella del soldato che rappresenterà tutti i caduti senza nome. Il viaggio in treno verso Roma dura cinque giorni, con folle silenziose lungo i binari; il 4 novembre 1921 il Milite Ignoto è sepolto a Roma, all’Altare della Patria. Sono morti più di seicentomila soldati italiani.",
"Dopo la guerra quasi ogni paese d’Italia costruisce nella piazza o davanti alla chiesa un monumento ai caduti, con l’elenco dei nomi dei giovani che non sono tornati. Il 4 novembre, ogni anno, la gente porta fiori e le campane suonano.",
"All’inizio del Novecento Roma è la capitale del Regno d’Italia, con più di mezzo milione di abitanti, i tram, i ministeri, le antiche rovine e il Papa in Vaticano. Nel 1911, per i cinquant’anni dell’unità d’Italia, viene inaugurato in Piazza Venezia il grande monumento a Vittorio Emanuele II, il Vittoriano, che dal 1921 ospita anche la tomba del Milite Ignoto e per questo si chiama Altare della Patria.",
"Il 6 gennaio 1907, nel quartiere popolare di San Lorenzo, Maria Montessori, una delle prime donne a laurearsi in medicina in Italia, apre la prima Casa dei Bambini, una scuola per circa cinquanta bambini piccoli. Le aule sono a misura di bambino, con tavolini bassi, scaffali e materiali da toccare, e i bambini imparano facendo da soli. Il metodo Montessori viene adottato in tutto il mondo.",
"Nell’Istituto di fisica di via Panisperna lavorano i \"ragazzi di via Panisperna\": Enrico Fermi, nato a Roma nel 1901, con Franco Rasetti, Edoardo Amaldi, Emilio Segrè, Ettore Majorana, Bruno Pontecorvo e altri. Il 22 ottobre 1934 scoprono che un pezzo di paraffina, o l’acqua della vasca dei pesci rossi nel giardino, rallenta i neutroni e li rende molto più efficaci: sono i \"neutroni lenti\". Per questa ricerca Fermi riceve il premio Nobel per la fisica nel 1938.",
"Nel 1922, dopo la \"marcia su Roma\" del 28 ottobre, Benito Mussolini diventa capo del governo e negli anni seguenti l’Italia diventa un regime con un solo partito, senza libertà di stampa e di parola. Il regime costruisce opere pubbliche, bonifica terre e controlla scuola, radio e cinema; nel 1929, con i Patti Lateranensi, nasce lo Stato della Città del Vaticano. Per questi anni il tono è descrittivo e sobrio.",
"Il 28 aprile 1937 vengono inaugurati a Roma gli studi di Cinecittà, sulla via Tuscolana: 73 edifici con 21 teatri di posa, progettati da Gino Peressutti, chiamati la \"Hollywood sul Tevere\". Qui, nei decenni seguenti, si girano grandi film italiani e internazionali, come \"Ben-Hur\" nel 1959 e \"La dolce vita\" di Federico Fellini nel 1960.",
"Nel giugno 1934 l’Italia ospita il secondo Campionato del mondo di calcio e lo vince: il 10 giugno 1934 gli azzurri, guidati dall’allenatore Vittorio Pozzo, battono la Cecoslovacchia nella finale di Roma. L’Italia si ripeterà quattro anni dopo, nel 1938, in Francia.",
"Nell’autunno 1938 il regime emana le leggi razziali, che tolgono molti diritti ai cittadini italiani ebrei: scuola, lavoro, università. Molte persone lasciano l’Italia, fra cui scienziati e artisti. Enrico Fermi, che ha sposato Laura Capon, di famiglia ebraica, riceve il premio Nobel a Stoccolma nel dicembre del 1938 e di lì parte per gli Stati Uniti con la famiglia. Il tono è sobrio e rispettoso.",
"Fra il 1940 e il 1943 Napoli è una delle città italiane più bombardate: la gente corre nei rifugi, spesso nelle antiche gallerie sotto la città, con materassi e pentole. L’8 settembre 1943 l’Italia annuncia l’armistizio con gli Alleati, ma la guerra continua con l’occupazione tedesca. Il tono è sobrio e rispettoso.",
"Dal 27 al 30 settembre 1943 i napoletani, ragazzi, donne, uomini di ogni mestiere, si ribellano ai tedeschi e li costringono a lasciare la città, prima ancora dell’arrivo degli Alleati, che entrano a Napoli il 1° ottobre. Per questo la città riceve la medaglia d’oro al valor militare. Fra i più giovani c’è Gennarino Capuozzo, un ragazzo di dodici anni.",
"Il 18 marzo 1944 il Vesuvio erutta: una colata di lava distrugge i paesi di San Sebastiano e Massa di Somma e una pioggia di cenere cade su tutta l’area; gli aerei alleati vengono danneggiati. Per molti napoletani, già provati dalla guerra, è un altro colpo. Si dice che il Vesuvio sia \"’o Vesuvio\", un vicino di casa da rispettare.",
"Il 25 aprile 1945 l’Italia del Nord è liberata dai nazisti e dai fascisti: oggi è la Festa della Liberazione. La guerra in Europa finisce a maggio. In agosto, il 6 e il 9, due bombe atomiche cadono su Hiroshima e Nagasaki, in Giappone, e la guerra finisce definitivamente: il mondo entra nell’era atomica. Il tono è sobrio e rispettoso.",
"Nel marzo del 1945 al Teatro San Carlo va in scena \"Napoli milionaria!\", la commedia di Eduardo De Filippo sulla città che sopravvive alla guerra fra borsa nera e miseria. Si chiude con la famosa frase di speranza: \"Adda passà ’a nuttata\", che vuol dire: \"deve passare la notte\". Eduardo la scrive e la recita con la sua compagnia, \"Il Teatro di Eduardo\".",
"Dopo la guerra si fa la fila per il pane e per il sapone; c’è la borsa nera, il mercato clandestino dove si vende e si compra di tutto. I bambini, gli scugnizzi, lustrano scarpe e vendono sigarette agli americani. Poi, piano piano, tornano la pizza, il caffè e le feste di quartiere.",
"Il 2 giugno 1946 gli italiani votano con il referendum se essere una monarchia o una repubblica, e per la prima volta in tutta l’Italia votano anche le donne. Vince la Repubblica; nello stesso giorno si elegge l’Assemblea Costituente. Fra le 21 donne elette ci sono anche madri e maestre. Il re Umberto II lascia l’Italia.",
"La Costituzione della Repubblica italiana è approvata dall’Assemblea Costituente il 22 dicembre 1947 ed entra in vigore il 1° gennaio 1948. Fra i suoi principi ci sono la libertà, l’uguaglianza e il lavoro. Dal 1948 il Piano Marshall, un programma di aiuti americani, porta in Europa e in Italia macchine, cibo e denaro per ricostruire le città.",
"Nel dopoguerra registi come Roberto Rossellini e Vittorio De Sica raccontano l’Italia vera, con attori presi dalla strada, nelle strade vere. Un episodio di \"Paisà\", di Rossellini, si svolge proprio a Napoli; \"Sciuscià\" di De Sica, del 1946, racconta due ragazzi lustrascarpe. Il neorealismo è il cinema italiano più celebre del mondo.",
"Nel 1954 Eduardo riapre il Teatro San Ferdinando, un teatro del Settecento distrutto dalle bombe, che lui ha ricostruito a sue spese in un quartiere popolare di Napoli. Qui continua a recitare e a scrivere commedie come \"Filumena Marturano\" (1946) e \"Questi fantasmi!\" (1946).",
"La Fiat (Fabbrica Italiana Automobili Torino) nasce nel 1899 e diventa la più grande industria italiana. Nel 1939 apre lo stabilimento di Mirafiori e negli anni Cinquanta Torino diventa la città dell’automobile. Il Lingotto, la fabbrica del 1923 con la pista sul tetto, è famoso in tutto il mondo.",
"Nei primi anni del Novecento Torino è la prima città italiana del cinema. Nel 1914 qui si gira \"Cabiria\", un grande film storico sull’antica Roma; per la prima volta la macchina da presa si muove su un carrello. Nel 1911 Torino ospita anche l’Esposizione Internazionale per i cinquant’anni dell’unità d’Italia.",
"Il 4 luglio 1957 la Fiat presenta la Nuova 500, un’utilitaria piccola e semplice, progettata da Dante Giacosa, che costa circa 490.000 lire. È la macchina delle famiglie, delle vacanze al mare e della prima patente. È piccola, ha un motore di due cilindri a bordo dietro e il tettuccio apribile di tela.",
"La RAI inizia le trasmissioni televisive il 3 gennaio 1954. All’inizio la gente guarda la televisione al bar o a casa dei vicini. Con \"Lascia o raddoppia?\", presentato da Mike Bongiorno dal 1955, la strada si svuota per guardare il quiz. Dal 1957 ogni sera c’è \"Carosello\": pubblicità raccontate con cartoni animati e personaggi, subito prima della buonanotte dei bambini.",
"Negli anni Cinquanta e Sessanta milioni di italiani lasciano il Sud e le campagne per lavorare nelle fabbriche del Nord. Arrivano con le valigie di cartone legate con lo spago, spesso in treno, e trovano stanze in affitto con il letto condiviso; a volte i cartelli dicono \"Non si affitta ai meridionali\". È una storia di fatica ma anche di cambiamento.",
"Nel 1960 Roma ospita i Giochi olimpici: l’etiope Abebe Bikila vince la maratona correndo a piedi nudi sull’antica via Appia. Nel 1961 Torino ospita \"Italia ’61\", l’esposizione per i cento anni dell’unità d’Italia. Nel 1964 apre l’Autostrada del Sole, da Milano a Napoli, 760 chilometri che uniscono l’Italia.",
"Nel 1969 gli operai di Torino e di tutta l’Italia scioperano e manifestano per salari più giusti e per condizioni di lavoro migliori. Nel 1970 viene approvato lo Statuto dei lavoratori, che dà più diritti a chi lavora. Il tono è sobrio.",
"Il 20 luglio 1969 gli astronauti americani Neil Armstrong e Buzz Aldrin camminano sulla Luna, in diretta televisiva guardata da centinaia di milioni di persone, anche in Italia, in piena notte, davanti a piccoli televisori in bianco e nero. La RAI trasmette la diretta con Tito Stagno e Ruggero Orlando.",
"Palermo ha antichi mercati, come Ballarò, la Vucciria e il Capo, dove i venditori gridano \"abbanniano\" (si dice così in dialetto) per attirare i clienti. Qui si mangiano le panelle (frittelle di farina di ceci), il pane con la milza e le arancine, le palline di riso fritte con ragù. La città racconta nella sua cucina secoli di dominazioni arabe e normanne.",
"Il Teatro Massimo, inaugurato nel 1897, è uno dei più grandi teatri lirici d’Europa. Dal 1974 al 1997 rimane chiuso per restauri che durano ventitré anni, e finalmente riapre il 12 maggio 1997. La sua scalinata è una delle scene più famose della città, e compare anche nel film \"Il Padrino - Parte III\".",
"Ai Quattro Canti, incrocio di due strade antiche, quattro facciate barocche con fontane, statue e stemmi dividono Palermo in quattro quartieri. A due passi si trova la Cattedrale, in cui si mescolano stili normanni, arabi e gotici, e Palazzo dei Normanni, con la splendida Cappella Palatina decorata di mosaici dorati.",
"Negli anni Ottanta la mafia siciliana, Cosa Nostra, uccide magistrati, poliziotti e politici. A Palermo i giudici Rocco Chinnici e poi Antonino Caponnetto costituiscono il \"pool antimafia\", un gruppo di magistrati che lavora in squadra, con Giovanni Falcone, Paolo Borsellino, Giuseppe Di Lello e Leonardo Guarnotta. Per la prima volta seguono i soldi e i conti bancari. Il tono è sobrio e rispettoso.",
"Il Maxiprocesso di Palermo comincia il 10 febbraio 1986 in un’aula bunker costruita accanto al carcere dell’Ucciardone: 475 imputati, più di trecento avvocati e centinaia di testimoni. La sentenza arriva il 16 dicembre 1987, con 19 ergastoli e centinaia di anni di carcere. Per la prima volta lo Stato dimostra che la mafia esiste e che si può condannare. Il tono è sobrio.",
"L’11 luglio 1982, a Madrid, l’Italia batte la Germania Ovest per 3 a 1 e vince il Mondiale di calcio. In tribuna il presidente della Repubblica Sandro Pertini esulta con la pipa in mano. Tutta l’Italia, anche Palermo, scende in strada con le bandiere.",
"Il 23 maggio 1992, sull’autostrada vicino a Capaci, un attentato uccide Giovanni Falcone, sua moglie Francesca Morvillo e tre agenti della scorta: Vito Schifani, Rocco Dicillo e Antonio Montinaro. Il 19 luglio 1992, in via D’Amelio, a Palermo, un altro attentato uccide Paolo Borsellino e cinque agenti: Emanuela Loi, Agostino Catalano, Vincenzo Li Muli, Walter Eddie Cosina e Claudio Traina. Il tono è molto sobrio e rispettoso; non si mostra violenza.",
"Dopo il 1992 Palermo risponde: la gente appende lenzuola bianche ai balconi con scritte di protesta e di pace, e migliaia di persone, soprattutto giovani, scendono in strada per dire basta alla mafia. Davanti alla casa di Falcone, in via Notarbartolo, un grande ficus diventa \"l’Albero Falcone\", pieno di messaggi e di foto lasciati da chi passa. Ogni 23 maggio si ricorda con una grande manifestazione.",
"Nel febbraio 1992, a Milano, comincia l’inchiesta \"Mani pulite\" sulla corruzione di politici e imprenditori, che cambia la politica italiana. Gli italiani la seguono ogni sera in televisione, mentre i partiti storici si dissolvono. Nello stesso anno, a Maastricht, l’Italia firma anche il trattato che crea l’Unione europea.",
"Il CERN, il Laboratorio europeo di fisica delle particelle, nasce nel 1954 vicino a Ginevra, sul confine fra Svizzera e Francia, con dodici Paesi fondatori fra cui l’Italia. Qui scienziati di tanti Paesi lavorano insieme per capire di cosa è fatta la materia, senza fini militari. Tutti gli anni arrivano da tutto il mondo giovani ricercatori e tecnici.",
"Nel 1989 si inaugura il LEP, un anello sotterraneo lungo 27 chilometri dove si fanno scontrare elettroni e positroni quasi alla velocità della luce, per studiare le particelle. Prima, nel 1983, il CERN aveva scoperto le particelle W e Z, che spiegano una delle forze della natura, e per questo la fisica ottiene un premio Nobel nel 1984.",
"Nel marzo 1989, al CERN, il ricercatore britannico Tim Berners-Lee propone un sistema per condividere documenti collegandoli fra loro con i link; nel 1990 nasce il primo server e il primo browser. Il 30 aprile 1993 il CERN mette il World Wide Web a disposizione di tutti, gratuitamente. Il tono è curioso e semplice.",
"Il 30 aprile 1986, a Pisa, il Centro Nazionale Universitario di Calcolo Elettronico collega per la prima volta l’Italia a Internet, via satellite. In pochi anni le università, e poi le case, si collegano con il modem, che fa quel famoso rumore di fischi.",
"Il 9 novembre 1989 cade il Muro di Berlino, che divideva la città dal 1961: migliaia di persone passano da Berlino Est a Ovest. La Guerra fredda finisce e nel 1991 si dissolve l’Unione Sovietica. Nel 1990 la Germania si riunifica.",
"Il 7 febbraio 1992 a Maastricht dodici Paesi firmano il trattato che crea l’Unione europea. Il 1° gennaio 1999 nasce l’euro come moneta comune, prima solo nei conti e nelle banche; le monete e le banconote arriveranno nelle tasche degli italiani nel 2002, al posto della lira.",
"Nel 1999 si parla del \"millennium bug\": si teme che i computer, che scrivono l’anno con due sole cifre, possano confondere il 2000 con il 1900. Alla fine non succede quasi niente, e la mezzanotte del 31 dicembre 1999 si festeggia in tutto il mondo con fuochi d’artificio, brindisi e dirette televisive.",
"Sul bordo della notte, davanti a Pierpaolo, lo schermo di un computer del CERN si allarga come una finestra. Dentro appare una rete di mille luci che collegano la Liguria, la Lombardia, il Friuli, Roma, Napoli, Torino, Palermo, Ginevra e tutti i luoghi del mondo, come un grande filo luminoso. Ogni luce è una persona incontrata lungo la strada. La rete si allarga finché la luce diventa bianca e il viaggio finisce, e il Novecento resta dietro di lui."
];
const NAME={"nv_nino": "Nino, il camallo", "nv_toscanini": "Arturo Toscanini, il direttore", "nv_agnese": "Agnese, la portatrice", "nv_fermi": "Enrico Fermi, il fisico", "nv_eduardo": "Eduardo De Filippo, il drammaturgo", "nv_gino": "Gino, l’operaio", "nv_falcone": "Giovanni Falcone, il magistrato", "nv_elena": "Elena, la tecnica del CERN"};
const GREET={
"nv_nino": "Salve, Pierpaolo! Aspetta che finisco di scaricare il carbone, tanto qui non si ferma mai nessuno. Sono Nino, camallo: porto pesi sulle spalle da quando avevo tredici anni, e di mugugnare non mi stanco mai.",
"nv_toscanini": "Salve, Pierpaolo! Fai piano, che stiamo provando: se sbagli un attacco, ti butto fuori io. Sono Arturo Toscanini, dirigo la Scala, e per me la musica si fa bene, o non si fa.",
"nv_agnese": "Salve, Pierpaolo. Cammina piano e sta’ attento dove metti i piedi: la neve nasconde i sassi. Sono Agnese, di Timau: porto su la gerla, perché i nostri soldati hanno bisogno di mangiare e noi donne abbiamo le gambe buone.",
"nv_fermi": "Salve, Pierpaolo! Vieni, ma non sporcare il tavolo: stiamo facendo un esperimento con un blocco di paraffina. Sono Enrico Fermi, fisico: faccio domande alla natura e a volte, con un po’ di fortuna, la natura risponde.",
"nv_eduardo": "Ué, Pierpaolo, salve. Vieni, siediti qui, in platea: il teatro è vuoto, ma domani sera sarà pieno. Sono Eduardo De Filippo: scrivo commedie sulla vita vera, e la vita vera, a Napoli, è la migliore commedia.",
"nv_gino": "Salve, Pierpaolo! Aspetta che suoni la sirena, che dopo ti offro un caffè. Sono Gino, operaio alla Fiat: faccio le macchine che altri comprano, e io intanto risparmio per comprarmene una.",
"nv_falcone": "Salve, Pierpaolo. Entra pure, ma non spostare le carte: qui ogni foglio ha il suo posto. Sono Giovanni Falcone, faccio il giudice a Palermo, e il mio lavoro è semplice da dire: capire come funziona la mafia e provarlo.",
"nv_elena": "Salve, Pierpaolo! Fai piano, sono turni di notte e qui il silenzio è sacro. Sono Elena, lavoro con i computer che raccolgono i dati del LEP: se hai domande, siediti pure qui vicino."
};

/* ---- cielo: alba perla e rosata, mattina velata, tarda mattina bianca e fredda, mezzogiorno abbagliante, primo pomeriggio vivido, pomeriggio piatto e fumoso, tardo pomeriggio arancio, tramonto, notte svizzera limpida ---- */
const SKY=[[0,['#aab0c8','#e8d0d8','#f4e2d8']],[1800,['#9ab4d8','#d8e0ec','#f4eadc']],[3300,['#8ab0dc','#cfdcec','#eeeae0']],[6200,['#b8c4d0','#dce2e8','#eef0f0']],[9100,['#4a9cec','#a8d4f4','#fbf4e0']],[12000,['#2a8ce8','#78c4f4','#f4f4f0']],[16100,['#9ab0c0','#d0d8dc','#e4e0d4']],[19400,['#7aa0d0','#e8d0a0','#f8d890']],[21200,['#8a8cc0','#e8b0a0','#f8c080']],[22200,['#6a5aa4','#d8789c','#f6b888']],[22900,['#2a2a6a','#5a3a7a','#c86a6a']],[23500,['#060a28','#0c1440','#142050']],[26500,['#04081e','#0a1238','#121c48']]];
function skyAt(xs){let i=0;while(i<SKY.length-2&&xs>SKY[i+1][0])i++;const a=SKY[i],b=SKY[i+1],u=cl((xs-a[0])/(b[0]-a[0]),0,1);return[0,1,2].map(k=>mixs(a[1][k],b[1][k],u))}
const nube=(g,x,y,s,c)=>{el(g,c,x,y,34*s,6*s);el(g,c,x-18*s,y+2*s,22*s,5*s);el(g,c,x+20*s,y+2*s,24*s,5*s)};
